<template>
  <div class="tire-app">
    <Sidebar />
    <main class="tire-main">
      <header class="tire-topbar">
        <label class="top-search">⌕ <input v-model="search" placeholder="Plaka, marka, model, lastik seri no. ile arama yapın..." /></label>
        <div class="top-user"><span class="bell">♧<i>3</i></span><span class="avatar">{{ initials }}</span><span><b>{{ customerName }}</b><small>Filo Yöneticisi</small></span><span>⌄</span></div>
      </header>
      <div class="tire-content">
        <div class="page-heading">
          <div><div class="title-line"><span class="wheel-icon">◉</span><h1>Lastik Yönetimi</h1></div><p>Araçlarınızdaki lastiklerin durumunu takip edin, değişim ve rotasyon planlarını yönetin.</p></div>
          <button class="primary-btn" @click="openCreate">＋ Yeni Lastik Kaydı</button>
        </div>
        <div class="overview-grid">
          <article class="metric-card"><span class="metric-icon blue">◉</span><div><small>Toplam Lastik</small><strong>{{ tires.length }}</strong></div><em>Filonuza bağlı</em></article>
          <article class="metric-card"><span class="metric-icon red">⚠</span><div><small>Değişim Bekleyen</small><strong>{{ needsChangeCount }}</strong></div><em>Durum takibi</em></article>
          <article class="metric-card"><span class="metric-icon blue">⟳</span><div><small>Rotasyon Bekleyen</small><strong>{{ rotationDueCount }}</strong></div><em>6 ayı aşan</em></article>
          <article class="metric-card"><span class="metric-icon red">⚠</span><div><small>Mücbir Durum</small><strong>{{ criticalCount }}</strong></div><em>Kontrol gerekli</em></article>
        </div>
        <div class="dashboard-grid">
          <section class="left-column">
            <div class="filter-bar">
              <label class="filter-search">⌕ <input v-model="search" placeholder="Plaka, marka, model, lastik seri no. ile arama..." /></label>
              <label><small>Araç Grubu</small><select v-model="vehicleFilter"><option value="all">Tümü</option><option v-for="group in vehicleGroups" :key="group">{{ group }}</option></select></label>
              <label><small>Lastik Durumu</small><select v-model="statusFilter"><option value="all">Tümü</option><option>İyi</option><option>Yaklaşan</option><option>Değişim Gerekli</option><option>Mücbir Durum</option></select></label>
              <label><small>Mevsim</small><select v-model="seasonFilter"><option value="all">Tümü</option><option>Yaz</option><option>Kış</option><option>Dört Mevsim</option></select></label>
              <label class="date-range"><small>Kontrol Tarihi</small><input v-model="fromDate" type="date" /></label>
              <button class="filter-btn" @click="page = 1">☷ Filtrele</button>
            </div>
            <section class="panel">
              <div class="panel-title"><h2><span>◉</span> Lastik Listesi</h2><div class="table-actions"><button :disabled="!selectedIds.length" @click="rotateSelected">⟳ Seçilenleri Rotasyona Al</button><button @click="exportCsv">↓ Dışa Aktar</button></div></div>
              <div class="table-scroll"><table>
                <thead><tr><th><input type="checkbox" :checked="allVisibleSelected" @change="toggleVisible" /></th><th>Plaka</th><th>Araç / Model</th><th>Lastik Markası</th><th>Ebat</th><th>Takım No</th><th>Üretim Tarihi</th><th>Değişim Tarihi</th><th>Durum</th><th>Kalan Km / Süre</th><th>İşlemler</th></tr></thead>
                <tbody>
                  <tr v-for="t in paginatedTires" :key="t.id">
                    <td><input type="checkbox" :checked="selectedIds.includes(t.id)" @change="toggleSelected(t.id)" /></td>
                    <td><button class="plate-link" @click="goToVehicle(t.vehicle_id)">{{ t.plate }}</button></td>
                    <td><div class="car-cell"><span class="mini-car">🚘</span><span>{{ t.vehicle_brand }} {{ t.vehicle_model }}<small>{{ t.vehicle_year }} · {{ t.size }}</small></span></div></td>
                    <td>{{ t.brand }}</td><td>{{ t.size }}</td><td>{{ t.set_no || '—' }}</td><td>{{ month(t.production_date) }}</td><td>{{ month(t.changed_at || t.installed_at) }}</td>
                    <td><span class="status-pill" :class="statusClass(t)"><i></i>{{ tireStatus(t) }}</span></td><td>{{ t.remaining_km == null ? '—' : number(t.remaining_km) + ' km' }}</td>
                    <td><div class="row-actions"><button title="İşlem kaydet" @click="openOperation(t)">⟳</button><button title="Düzenle" @click="editTire(t)">•••</button></div></td>
                  </tr>
                  <tr v-if="!paginatedTires.length"><td colspan="11" class="empty-state"><b>Filtrelere uygun lastik kaydı yok</b><small>Yeni lastik kaydı ekleyerek aracınızla eşleştirin.</small></td></tr>
                </tbody>
              </table></div>
              <footer class="table-footer"><span>Toplam {{ filteredTires.length }} lastik kaydından {{ pageStart }}–{{ pageEnd }} görüntüleniyor</span><div class="pagination"><button :disabled="page <= 1" @click="page--">‹</button><button v-for="p in totalPages" :key="p" :class="{ current: p === page }" @click="page = p">{{ p }}</button><button :disabled="page >= totalPages" @click="page++">›</button></div></footer>
            </section>
            <div class="lower-grid">
              <section class="panel"><div class="panel-title"><h2><span>◉</span> Lastik Markaları</h2></div><div class="brand-list"><div v-for="b in brandStats" :key="b.name" class="brand-row"><span>{{ b.name }}</span><div class="bar"><i :style="{ width: b.percent + '%', background: b.color }"></i></div><b>{{ b.count }}</b></div><p v-if="!brandStats.length" class="muted-empty">Henüz kayıtlı lastik markası yok.</p></div></section>
              <section class="panel"><div class="panel-title"><h2><span>◉</span> Mevsimsel Dağılım</h2></div><div class="season-cards"><div v-for="s in seasonStats" :key="s.name" class="season-item"><span>{{ s.icon }}</span><b>{{ s.count }}</b><small>{{ s.name }}</small><em>%{{ s.percent }}</em></div></div></section>
              <section class="tip-card"><div>ⓘ</div><section><b>Öneri</b><p>Lastiklerinizi 6 ayda bir rotasyon yapmanız lastik ömrünü uzatır ve sürüş güvenliğini artırır.</p><button @click="showGuide = !showGuide">Detaylı Rehber →</button><p v-if="showGuide">Rotasyonu araç üreticisinin önerdiği düzene göre yaptırın. Diş derinliğini, basıncı ve üretim tarihini düzenli kontrol edin.</p></section></section>
            </div>
          </section>
          <aside class="right-column">
            <section class="panel summary-panel"><div class="panel-title"><h2><span>♧</span> Lastik Durum Özeti</h2></div><div class="summary-body"><div class="donut" :style="donutStyle"><div><b>{{ tires.length }}</b><small>Toplam Lastik</small></div></div><div class="legend"><div><i class="green"></i><span>İyi</span><b>{{ statusCounts.good }}</b><small>{{ percent(statusCounts.good) }}%</small></div><div><i class="amber"></i><span>Yaklaşan</span><b>{{ statusCounts.soon }}</b><small>{{ percent(statusCounts.soon) }}%</small></div><div><i class="red"></i><span>Değişim Gerekli</span><b>{{ statusCounts.change }}</b><small>{{ percent(statusCounts.change) }}%</small></div><div><i class="slate"></i><span>Mücbir Durum</span><b>{{ statusCounts.critical }}</b><small>{{ percent(statusCounts.critical) }}%</small></div></div></div></section>
            <section class="panel"><div class="panel-title"><h2><span>▦</span> Yaklaşan İşlemler</h2></div><ol class="timeline"><li v-for="t in upcomingTires.slice(0,3)" :key="'up'+t.id" :class="statusClass(t)"><i></i><div><b>{{ t.plate }}</b><span class="timeline-badge" :class="statusClass(t)">{{ tireStatus(t) }}</span><small>{{ t.remaining_km == null ? 'Kontrol planlaması gerekli' : number(t.remaining_km) + ' km kaldı' }}</small><p>{{ t.brand }} · {{ t.size }} lastik değişimi planlanmalı</p></div></li><li v-if="!upcomingTires.length" class="no-timeline">Yaklaşan lastik işlemi yok.</li></ol><button class="outline-wide" @click="showHistory = true">Tüm İşlemleri Görüntüle</button></section>
            <section class="panel"><div class="panel-title"><h2><span>⚒</span> Son Bakım İşlemleri</h2></div><ol class="timeline"><li v-for="op in operations.slice(0,3)" :key="op.id" class="done"><i></i><div><b>{{ op.plate }}</b><span class="timeline-badge completed">✓ {{ op.status }}</span><small>{{ op.type }} yapıldı</small><p>{{ dateLabel(op.date) }}<template v-if="op.mileage != null"> · {{ number(op.mileage) }} km</template></p></div></li><li v-if="!operations.length" class="no-timeline">Henüz bakım işlemi kaydı yok.</li></ol><button class="outline-wide" @click="showHistory = true">Tüm Bakım Kayıtlarını Görüntüle</button></section>
          </aside>
        </div>
      </div>
    </main>
    <div v-if="modal" class="modal-backdrop" @click.self="modal = ''"><section class="modal-card"><header><div><small>LASTİK YÖNETİMİ</small><h2>{{ modal === 'operation' ? 'Lastik işlemi kaydet' : editingId ? 'Lastik kaydını düzenle' : 'Yeni lastik kaydı' }}</h2></div><button class="close-btn" @click="modal = ''">×</button></header>
      <form v-if="modal === 'tire'" @submit.prevent="saveTire">
        <label>Araç<select v-model="form.vehicle_id" required><option value="" disabled>Araç seçin</option><option v-for="v in vehicles" :key="v.id" :value="v.id">{{ v.plate }} · {{ v.brand }} {{ v.model }}</option></select></label>
        <div class="form-grid"><label>Lastik Markası<input v-model.trim="form.brand" required placeholder="Michelin" /></label><label>Lastik Ebatı<input v-model.trim="form.size" required placeholder="205/55 R16" /></label><label>Takım No<input v-model.trim="form.set_no" placeholder="ML-00123" /></label><label>Mevsim<select v-model="form.season"><option>Yaz</option><option>Kış</option><option>Dört Mevsim</option></select></label><label>Üretim Tarihi<input v-model="form.production_date" type="month" /></label><label>Takılma / Değişim Tarihi<input v-model="form.changed_at" type="date" /></label><label>Son Kontrol Tarihi<input v-model="form.inspected_at" type="date" /></label><label>Diş Derinliği (mm)<input v-model.number="form.tread_depth_mm" min="0" max="20" step="0.1" type="number" /></label><label>Durum<select v-model="form.status"><option>İyi</option><option>Yaklaşan</option><option>Değişim Gerekli</option><option>Mücbir Durum</option></select></label><label>Kalan kullanım (km)<input v-model.number="form.remaining_km" min="0" type="number" /></label></div>
        <label>Notlar<textarea v-model.trim="form.notes" rows="3" placeholder="Lastiklerle ilgili not..." /></label><p v-if="formError" class="form-error">{{ formError }}</p><footer><button type="button" class="cancel-btn" @click="modal = ''">Vazgeç</button><button class="primary-btn" :disabled="saving">{{ saving ? 'Kaydediliyor…' : 'Kaydet' }}</button></footer>
      </form>
      <form v-else-if="modal === 'operation'" @submit.prevent="saveOperation"><div class="operation-car"><span>🚘</span><b>{{ operationTire?.plate }} · {{ operationTire?.vehicle_brand }} {{ operationTire?.vehicle_model }}</b></div><label>İşlem türü<select v-model="operationForm.type"><option>Rotasyon</option><option>Lastik değişimi</option><option>Basınç kontrolü</option><option>Diş derinliği kontrolü</option><option>Balans</option></select></label><div class="form-grid"><label>İşlem tarihi<input v-model="operationForm.date" type="date" required /></label><label>Araç kilometresi<input v-model.number="operationForm.mileage" min="0" type="number" /></label></div><label>Açıklama<textarea v-model.trim="operationForm.description" rows="3" placeholder="İşlem notu" /></label><p v-if="formError" class="form-error">{{ formError }}</p><footer><button type="button" class="cancel-btn" @click="modal = ''">Vazgeç</button><button class="primary-btn" :disabled="saving">İşlemi Kaydet</button></footer></form>
    </section></div>
    <div v-if="showHistory" class="modal-backdrop" @click.self="showHistory = false"><section class="modal-card history-modal"><header><div><small>ARAÇ BAKIM GEÇMİŞİ</small><h2>Lastik işlem kayıtları</h2></div><button class="close-btn" @click="showHistory = false">×</button></header><div v-if="operations.length" class="history-list"><article v-for="op in operations" :key="op.id"><span>⟳</span><div><b>{{ op.plate }} · {{ op.type }}</b><small>{{ dateLabel(op.date) }}<template v-if="op.mileage != null"> · {{ number(op.mileage) }} km</template></small><p>{{ op.description || 'İşlem tamamlandı.' }}</p></div><em>{{ op.status }}</em></article></div><p v-else class="muted-empty">Henüz lastik işlem kaydı yok.</p></section></div>
  </div>
</template>

<script setup>
import { ref, reactive, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import Sidebar from '../components/Sidebar.vue'
const router = useRouter()
const customerId = localStorage.getItem('fleetcar_customer_id')
const customerName = localStorage.getItem('fleetcar_customer_name') || 'Filo Yöneticisi'
const initials = customerName.split(/\s+/).slice(0,2).map(p => p[0]).join('').toLocaleUpperCase('tr-TR')
const tires = ref([]), vehicles = ref([]), operations = ref([])
const search = ref(''), statusFilter = ref('all'), seasonFilter = ref('all'), vehicleFilter = ref('all'), fromDate = ref('')
const page = ref(1), pageSize = 10, selectedIds = ref([]), modal = ref(''), showHistory = ref(false), showGuide = ref(false), saving = ref(false), formError = ref(''), editingId = ref(null), operationTire = ref(null)
const today = new Date().toISOString().slice(0,10)
const emptyForm = () => ({ vehicle_id:'',brand:'',size:'',set_no:'',season:'Dört Mevsim',production_date:'',installed_at:'',changed_at:today,inspected_at:'',tread_depth_mm:null,status:'İyi',remaining_km:null,position:'',notes:'' })
const form = reactive(emptyForm())
const operationForm = reactive({ type:'Rotasyon',date:today,mileage:null,description:'' })
const vehicleGroups = computed(() => [...new Set(vehicles.value.map(v => v.vehicle_segment || v.vehicle_type).filter(Boolean))].sort())
const filteredTires = computed(() => tires.value.filter(t => {
  const query = search.value.trim().toLocaleLowerCase('tr-TR')
  const haystack = [t.plate,t.vehicle_brand,t.vehicle_model,t.brand,t.size,t.set_no].join(' ').toLocaleLowerCase('tr-TR')
  const v = vehicles.value.find(item => item.id === t.vehicle_id)
  return (!query || haystack.includes(query)) && (statusFilter.value === 'all' || tireStatus(t) === statusFilter.value) && (seasonFilter.value === 'all' || t.season === seasonFilter.value) && (vehicleFilter.value === 'all' || (v?.vehicle_segment || v?.vehicle_type) === vehicleFilter.value) && (!fromDate.value || (t.inspected_at || '') >= fromDate.value)
}))
const totalPages = computed(() => Math.max(1,Math.ceil(filteredTires.value.length/pageSize)))
const paginatedTires = computed(() => filteredTires.value.slice((page.value-1)*pageSize,page.value*pageSize))
const pageStart = computed(() => filteredTires.value.length ? (page.value-1)*pageSize+1 : 0)
const pageEnd = computed(() => Math.min(page.value*pageSize,filteredTires.value.length))
const allVisibleSelected = computed(() => paginatedTires.value.length>0 && paginatedTires.value.every(t=>selectedIds.value.includes(t.id)))
function tireStatus(t){ return t.status || (Number(t.remaining_km)>10000?'İyi':Number(t.remaining_km)>3000?'Yaklaşan':'Değişim Gerekli') }
const needsChangeCount = computed(() => tires.value.filter(t=>['Yaklaşan','Değişim Gerekli'].includes(tireStatus(t))).length)
const rotationDueCount = computed(() => tires.value.filter(t=>{const d=new Date(t.changed_at||t.installed_at||'');return Number.isFinite(d.getTime())&&Date.now()-d.getTime()>183*86400000}).length)
const criticalCount = computed(() => tires.value.filter(t=>tireStatus(t)==='Mücbir Durum').length)
const statusCounts = computed(() => ({good:tires.value.filter(t=>tireStatus(t)==='İyi').length,soon:tires.value.filter(t=>tireStatus(t)==='Yaklaşan').length,change:tires.value.filter(t=>tireStatus(t)==='Değişim Gerekli').length,critical:criticalCount.value}))
const percent = n => tires.value.length ? Math.round(n*1000/tires.value.length)/10 : 0
const donutStyle = computed(() => { const values=[statusCounts.value.good,statusCounts.value.soon,statusCounts.value.change,statusCounts.value.critical], colors=['#13a66b','#f2b51c','#e94b55','#56647d'];let cursor=0;const stops=values.map((v,i)=>{const start=cursor;cursor+=percent(v);return colors[i]+' '+start+'% '+cursor+'%'});return {background:'conic-gradient('+stops.join(',')+')'} })
const upcomingTires = computed(() => tires.value.filter(t=>['Yaklaşan','Değişim Gerekli','Mücbir Durum'].includes(tireStatus(t))).sort((a,b)=>(a.remaining_km??Number.MAX_SAFE_INTEGER)-(b.remaining_km??Number.MAX_SAFE_INTEGER)))
const brandStats = computed(() => {const counts=tires.value.reduce((acc,t)=>(acc[t.brand||'Diğer']=(acc[t.brand||'Diğer']||0)+1,acc),{}),colors=['#1672ef','#f1a721','#18a86d','#8b5ad9','#3290b7'];return Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([name,count],i)=>({name,count,percent:Math.round(count*100/Math.max(1,tires.value.length)),color:colors[i%colors.length]}))})
const seasonStats = computed(() => ['Yaz','Kış','Dört Mevsim','Diğer'].map((name,i)=>{const count=tires.value.filter(t=>t.season===name||(name==='Diğer'&&!['Yaz','Kış','Dört Mevsim'].includes(t.season))).length;return{name:name==='Dört Mevsim'?'4 Mevsim':name,count,percent:percent(count),icon:['☀','❄','◉','◌'][i]}}))
function number(v){return Number(v||0).toLocaleString('tr-TR')}
function month(v){if(!v)return'—';const d=new Date(v.length===7?v+'-01':v);return Number.isNaN(d.getTime())?v:d.toLocaleDateString('tr-TR',{year:'numeric',month:'2-digit'})}
function dateLabel(v){if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?v:d.toLocaleDateString('tr-TR')}
function statusClass(t){return({'İyi':'good','Yaklaşan':'soon','Değişim Gerekli':'change','Mücbir Durum':'critical'})[tireStatus(t)]||'good'}
function toggleSelected(id){selectedIds.value=selectedIds.value.includes(id)?selectedIds.value.filter(x=>x!==id):[...selectedIds.value,id]}
function toggleVisible(e){const ids=paginatedTires.value.map(t=>t.id);selectedIds.value=e.target.checked?[...new Set([...selectedIds.value,...ids])]:selectedIds.value.filter(id=>!ids.includes(id))}
function goToVehicle(id){router.push('/dashboard/vehicles/'+encodeURIComponent(id))}
async function loadData(){if(!customerId){tires.value=[];vehicles.value=[];operations.value=[];return}const suffix='?customer_id='+encodeURIComponent(customerId);const [a,b,c]=await Promise.all([fetch('/api/tires'+suffix),fetch('/api/vehicles'+suffix),fetch('/api/tire-operations'+suffix)]);if(a.ok)tires.value=await a.json();if(b.ok)vehicles.value=await b.json();if(c.ok)operations.value=await c.json()}
function openCreate(){editingId.value=null;Object.assign(form,emptyForm());formError.value='';modal.value='tire'}
function editTire(t){editingId.value=t.id;Object.assign(form,{...emptyForm(),...t});formError.value='';modal.value='tire'}
async function saveTire(){saving.value=true;formError.value='';const payload={...form,remaining_km:form.remaining_km===''?null:form.remaining_km};const r=await fetch(editingId.value?'/api/tires/'+editingId.value:'/api/tires',{method:editingId.value?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).catch(()=>null);saving.value=false;if(!r?.ok){formError.value='Kayıt kaydedilemedi. Seçilen aracı ve alanları kontrol edin.';return}modal.value='';await loadData()}
function openOperation(t){operationTire.value=t;Object.assign(operationForm,{type:'Rotasyon',date:today,mileage:t.vehicle_mileage||null,description:''});formError.value='';modal.value='operation'}
async function saveOperation(){if(!operationTire.value)return;saving.value=true;formError.value='';const r=await fetch('/api/tire-operations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...operationForm,vehicle_id:operationTire.value.vehicle_id,tire_id:operationTire.value.id,status:'Tamamlandı'})}).catch(()=>null);saving.value=false;if(!r?.ok){formError.value='İşlem kaydedilemedi. Lütfen tekrar deneyin.';return}modal.value='';await loadData()}
async function rotateSelected(){const selected=tires.value.filter(t=>selectedIds.value.includes(t.id));if(!selected.length)return;saving.value=true;const results=await Promise.all(selected.map(t=>fetch('/api/tire-operations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({vehicle_id:t.vehicle_id,tire_id:t.id,type:'Rotasyon',date:today,mileage:t.vehicle_mileage,status:'Tamamlandı',description:'Lastik listesi üzerinden toplu rotasyon kaydı.'})})));saving.value=false;if(results.some(r=>!r.ok)){formError.value='Bazı rotasyon kayıtları oluşturulamadı.';return}selectedIds.value=[];await loadData()}
function exportCsv(){const cols=['Plaka','Araç','Lastik Markası','Ebat','Takım No','Üretim Tarihi','Değişim Tarihi','Mevsim','Durum','Kalan Km'];const rows=filteredTires.value.map(t=>[t.plate,(t.vehicle_brand||'')+' '+(t.vehicle_model||''),t.brand,t.size,t.set_no,t.production_date,t.changed_at||t.installed_at,t.season,tireStatus(t),t.remaining_km]);const csv=[cols,...rows].map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));a.download='fleetrent-lastik-listesi.csv';a.click();URL.revokeObjectURL(a.href)}
onMounted(loadData)
